CREATE TABLE public.ads_members (user_id uuid PRIMARY KEY, account_type text NOT NULL DEFAULT 'advertiser' CHECK (account_type IN ('advertiser','media_owner','both')), display_name text NOT NULL DEFAULT '', verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.ads_members TO authenticated; GRANT ALL ON public.ads_members TO service_role;
ALTER TABLE public.ads_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_members_read ON public.ads_members FOR SELECT TO authenticated USING (true);
CREATE POLICY ads_members_insert ON public.ads_members FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND verified=false);
CREATE POLICY ads_members_update ON public.ads_members FOR UPDATE TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.ads_member_verify_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.verified IS DISTINCT FROM OLD.verified AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Only administrators can verify media owners'; END IF; RETURN NEW; END $$;
CREATE TRIGGER ads_member_verify_guard BEFORE UPDATE ON public.ads_members FOR EACH ROW EXECUTE FUNCTION public.ads_member_verify_guard();
CREATE TABLE public.ads_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid, title text NOT NULL, media_owner text NOT NULL, category text NOT NULL, location text NOT NULL, audience text NOT NULL DEFAULT 'General public', description text NOT NULL DEFAULT '', format text NOT NULL DEFAULT '', price numeric CHECK(price>=0), duration_days integer NOT NULL DEFAULT 30 CHECK(duration_days>0), images text[] NOT NULL DEFAULT '{}', specifications jsonb NOT NULL DEFAULT '{}', packages jsonb NOT NULL DEFAULT '[]', available_from date NOT NULL DEFAULT CURRENT_DATE, available_until date NOT NULL DEFAULT (CURRENT_DATE + 365), reach bigint, reach_verified boolean NOT NULL DEFAULT false, instant_booking boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending_review' CHECK(status IN ('draft','pending_review','active','rejected','paused')), is_demo boolean NOT NULL DEFAULT false, latitude numeric, longitude numeric, created_at timestamptz NOT NULL DEFAULT now(), CHECK(available_until>=available_from));
GRANT SELECT ON public.ads_listings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.ads_listings TO authenticated; GRANT ALL ON public.ads_listings TO service_role;
ALTER TABLE public.ads_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_listing_public ON public.ads_listings FOR SELECT TO anon,authenticated USING (status='active');
CREATE POLICY ads_listing_owner_read ON public.ads_listings FOR SELECT TO authenticated USING(owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_listing_insert ON public.ads_listings FOR INSERT TO authenticated WITH CHECK(owner_user_id=auth.uid() AND status IN('draft','pending_review') AND is_demo=false AND reach_verified=false AND EXISTS(SELECT 1 FROM public.ads_members WHERE user_id=auth.uid() AND account_type IN('media_owner','both')));
CREATE POLICY ads_listing_update ON public.ads_listings FOR UPDATE TO authenticated USING(owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.ads_listing_review_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN IF NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id OR NEW.is_demo IS DISTINCT FROM OLD.is_demo OR NEW.reach_verified IS DISTINCT FROM OLD.reach_verified THEN RAISE EXCEPTION 'Protected listing fields'; END IF; IF NEW.status='active' THEN NEW.status:='pending_review'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER ads_listing_review_guard BEFORE UPDATE ON public.ads_listings FOR EACH ROW EXECUTE FUNCTION public.ads_listing_review_guard();
CREATE TABLE public.ads_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), advertiser_user_id uuid NOT NULL, listing_id uuid REFERENCES public.ads_listings(id), owner_user_id uuid, objective text NOT NULL, audience text NOT NULL, locations text NOT NULL, channels text[] NOT NULL DEFAULT '{}', budget numeric NOT NULL CHECK(budget>0), start_date date NOT NULL, end_date date NOT NULL, requirements text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'inquiry' CHECK(status IN('inquiry','quotation','negotiation','booking_confirmed','closed')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_date>=start_date));
GRANT SELECT,INSERT,UPDATE ON public.ads_requests TO authenticated; GRANT ALL ON public.ads_requests TO service_role; ALTER TABLE public.ads_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_requests_read ON public.ads_requests FOR SELECT TO authenticated USING(advertiser_user_id=auth.uid() OR owner_user_id=auth.uid() OR (owner_user_id IS NULL AND EXISTS(SELECT 1 FROM public.ads_members WHERE user_id=auth.uid() AND account_type IN('media_owner','both'))) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_requests_insert ON public.ads_requests FOR INSERT TO authenticated WITH CHECK(advertiser_user_id=auth.uid() AND status='inquiry' AND (listing_id IS NULL AND owner_user_id IS NULL OR EXISTS(SELECT 1 FROM public.ads_listings l WHERE l.id=listing_id AND l.status='active' AND l.owner_user_id IS NOT DISTINCT FROM ads_requests.owner_user_id)));
CREATE TABLE public.ads_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.ads_requests(id), owner_user_id uuid NOT NULL, amount numeric NOT NULL CHECK(amount>0), terms text NOT NULL, valid_until date NOT NULL, status text NOT NULL DEFAULT 'submitted' CHECK(status IN('submitted','accepted','rejected')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.ads_quotes TO authenticated; GRANT ALL ON public.ads_quotes TO service_role; ALTER TABLE public.ads_quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_quotes_read ON public.ads_quotes FOR SELECT TO authenticated USING(owner_user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.ads_requests r WHERE r.id=request_id AND r.advertiser_user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_quotes_insert ON public.ads_quotes FOR INSERT TO authenticated WITH CHECK(owner_user_id=auth.uid() AND status='submitted' AND EXISTS(SELECT 1 FROM public.ads_members WHERE user_id=auth.uid() AND account_type IN('media_owner','both')) AND EXISTS(SELECT 1 FROM public.ads_requests r WHERE r.id=request_id AND r.advertiser_user_id<>auth.uid() AND (r.owner_user_id=auth.uid() OR r.owner_user_id IS NULL)));
CREATE TABLE public.ads_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_id uuid UNIQUE NOT NULL REFERENCES public.ads_quotes(id), request_id uuid NOT NULL REFERENCES public.ads_requests(id), advertiser_user_id uuid NOT NULL, owner_user_id uuid NOT NULL, amount numeric NOT NULL, status text NOT NULL DEFAULT 'booking_confirmed' CHECK(status IN('booking_confirmed','payment_pending','campaign_active','completed','disputed','cancelled')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN('unpaid','paid','refunded')), commission_rate numeric NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ads_bookings TO authenticated; GRANT ALL ON public.ads_bookings TO service_role; ALTER TABLE public.ads_bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_bookings_read ON public.ads_bookings FOR SELECT TO authenticated USING(advertiser_user_id=auth.uid() OR owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ads_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid UNIQUE NOT NULL REFERENCES public.ads_bookings(id), advertiser_user_id uuid NOT NULL, owner_user_id uuid NOT NULL, title text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, proof_urls text[] NOT NULL DEFAULT '{}', report text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.ads_campaigns TO authenticated; GRANT ALL ON public.ads_campaigns TO service_role; ALTER TABLE public.ads_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_campaigns_read ON public.ads_campaigns FOR SELECT TO authenticated USING(advertiser_user_id=auth.uid() OR owner_user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_campaigns_update ON public.ads_campaigns FOR UPDATE TO authenticated USING(owner_user_id=auth.uid()) WITH CHECK(owner_user_id=auth.uid());
GRANT UPDATE(proof_urls,report) ON public.ads_campaigns TO authenticated; REVOKE UPDATE ON public.ads_campaigns FROM authenticated;
CREATE TABLE public.ads_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.ads_requests(id), sender_user_id uuid NOT NULL, body text NOT NULL CHECK(length(body)>0 AND length(body)<=5000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.ads_messages TO authenticated; GRANT ALL ON public.ads_messages TO service_role; ALTER TABLE public.ads_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_messages_read ON public.ads_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.ads_requests r WHERE r.id=request_id AND (r.advertiser_user_id=auth.uid() OR r.owner_user_id=auth.uid())) OR EXISTS(SELECT 1 FROM public.ads_quotes q WHERE q.request_id=ads_messages.request_id AND q.owner_user_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY ads_messages_insert ON public.ads_messages FOR INSERT TO authenticated WITH CHECK(sender_user_id=auth.uid() AND (EXISTS(SELECT 1 FROM public.ads_requests r WHERE r.id=request_id AND (r.advertiser_user_id=auth.uid() OR r.owner_user_id=auth.uid())) OR EXISTS(SELECT 1 FROM public.ads_quotes q WHERE q.request_id=ads_messages.request_id AND q.owner_user_id=auth.uid())));
CREATE TABLE public.ads_saved (user_id uuid NOT NULL, listing_id uuid NOT NULL REFERENCES public.ads_listings(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,listing_id));
GRANT SELECT,INSERT,DELETE ON public.ads_saved TO authenticated; GRANT ALL ON public.ads_saved TO service_role; ALTER TABLE public.ads_saved ENABLE ROW LEVEL SECURITY;
CREATE POLICY ads_saved_own ON public.ads_saved FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.ads_accept_quote(quote uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.ads_quotes; r public.ads_requests; b uuid; BEGIN SELECT * INTO q FROM public.ads_quotes WHERE id=quote FOR UPDATE; SELECT * INTO r FROM public.ads_requests WHERE id=q.request_id FOR UPDATE; IF r.advertiser_user_id IS DISTINCT FROM auth.uid() OR q.status<>'submitted' OR q.valid_until<CURRENT_DATE OR r.status='booking_confirmed' THEN RAISE EXCEPTION 'Quote cannot be accepted'; END IF; IF EXISTS(SELECT 1 FROM public.ads_listings WHERE id=r.listing_id AND is_demo) THEN RAISE EXCEPTION 'Demo inventory cannot be booked'; END IF; INSERT INTO public.ads_bookings(quote_id,request_id,advertiser_user_id,owner_user_id,amount) VALUES(q.id,r.id,auth.uid(),q.owner_user_id,q.amount) RETURNING id INTO b; INSERT INTO public.ads_campaigns(booking_id,advertiser_user_id,owner_user_id,title,start_date,end_date) VALUES(b,auth.uid(),q.owner_user_id,r.objective,r.start_date,r.end_date); UPDATE public.ads_quotes SET status='accepted' WHERE id=q.id; UPDATE public.ads_requests SET status='booking_confirmed' WHERE id=r.id; RETURN b; END $$;
REVOKE ALL ON FUNCTION public.ads_accept_quote(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.ads_accept_quote(uuid) TO authenticated;
CREATE INDEX ads_listings_category_location ON public.ads_listings(category,location,status); CREATE INDEX ads_requests_advertiser ON public.ads_requests(advertiser_user_id); CREATE INDEX ads_messages_request ON public.ads_messages(request_id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.ads_requests, public.ads_quotes, public.ads_bookings, public.ads_campaigns, public.ads_messages;
